UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 79, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 80, 7, NULL::text),(3, 208, 35, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 247, 323, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='0bc03197-02d2-5d6d-b3e1-17fb31dca1bc' AND md5(a.contenido)='5745efd5da8bada97ac516f0404e7623' RETURNING a.id,md5(a.contenido) hash;